const loading = true;
const loadEarlier = () => {};
const messages = [<Message key="question" from="user"><Message.Content>Check main.</Message.Content></Message>];

<ConversationList onScrollTop={loadEarlier} history={loading ? "loading" : "idle"}>
  {messages}
</ConversationList>

const loadEarlier = () => {};
const messages = [<Message key="question" from="user"><Message.Content>Check main.</Message.Content></Message>];

